import java.util.*;
interface Insurable {double calculateInsurance();}
abstract class Parcel {double weight,declaredValue;Parcel(double w,double v){weight=w;declaredValue=v;}abstract double calculateCharge();abstract String getType();double getInsurance(){if(this instanceof Insurable)return ((Insurable)this).calculateInsurance();return 0.0;}double calculateTotal(){return calculateCharge()+getInsurance();}}
class StandardParcel extends Parcel {StandardParcel(double w,double v){super(w,v);}double calculateCharge(){return 40+10*weight;}String getType(){return "STANDARD";}}
class ExpressParcel extends Parcel implements Insurable {ExpressParcel(double w,double v){super(w,v);}double calculateCharge(){return 80+15*weight;}public double calculateInsurance(){return declaredValue*.02;}String getType(){return "EXPRESS";}}
class FragileParcel extends Parcel implements Insurable {FragileParcel(double w,double v){super(w,v);}double calculateCharge(){return 40+10*weight+50;}public double calculateInsurance(){return declaredValue*.02;}String getType(){return "FRAGILE";}}
public class ParcelShippingDesk {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double grandTotal=0;for(int i=0;i<n;i++){String type=sc.next();double weight=sc.nextDouble(),value=sc.nextDouble();Parcel p;switch(type){case "STANDARD":p=new StandardParcel(weight,value);break;case "EXPRESS":p=new ExpressParcel(weight,value);break;default:p=new FragileParcel(weight,value);}double charge=p.calculateCharge(),insurance=p.getInsurance(),total=p.calculateTotal();System.out.printf("%s: Charge=%.2f Insurance=%.2f Total=%.2f%n",p.getType(),charge,insurance,total);grandTotal+=total;}System.out.printf("Grand Total: %.2f%n",grandTotal);sc.close();}}